    uint32_t padding = 1;

    auto outD = static_cast<uint32_t>((static_cast<int64_t>(d) + 2 * padding - ksize) / stride + 1);
    auto outH = static_cast<uint32_t>((static_cast<int64_t>(h) + 2 * padding - ksize) / stride + 1);
